def collect(extra=()):
    by={e['name']:e for e in load(B/'verification/kernel_axioms.json')['printed_receipts']};records=[]
    for id_,name,inputs,result,proofs in list(RECORDS)+list(extra):
        missing=[p for p in proofs if p not in by]
        if missing:raise RuntimeError('No receipt for '+', '.join(missing))
        records.append({'id':id_,'name':name,'inputs':inputs,'output_or_relation':result,'status':'KERNEL_CHECKED_TYPED_OPERATION','admissible_substitution':'Substitute only matching carrier types and supply every displayed binder; the scalar field 𝕜 and the ℓ² uniformity are hypotheses of the lift, not consequences of the exact carrier.','proofs':[by[p] for p in proofs]})
    save(B/'operad_delta.json',{'schema_version':2,'namespace':'HL-HILBERT-LIFT','records':records,'formal_operad_claim':'Scoped typed operations with kernel-checked relations and exact receipts; no complete higher-arity operad is claimed.','authority_effect':'None'})
    print(json.dumps({'records':len(records),'proofs':sum(len(r['proofs']) for r in records)}))
if __name__=='__main__':
    extra=json.loads((B/'tools/operad_extra.json').read_text(encoding='utf-8')) if (B/'tools/operad_extra.json').is_file() else []
    collect([tuple(e) for e in extra])
